properties.expression:
setCart((items) => {
        const existing = items.find((item) => item.productId === product.id)
        return existing
          ? items.map((item) => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item)
          : [...items, { productId: product.id, quantity: 1 }]
      })

